                echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="zp_prep_auto_retry"><input type="hidden" name="auto_id" value="'.esc_attr($s['id']).'">';wp_nonce_field('zp_prep_auto_retry');echo '<label><input type="checkbox" name="retry_ack" value="1" required> '.esc_html($known?'Sprawdziłem stan. Odczytujemy tę samą zapisaną odpowiedź bez nowego zlecenia.':'Sprawdziłem stan. Wynik poprzedniego żądania jest niepewny; świadome ponowienie może naliczyć koszt ponownie. Przy zmianie kalendarza potwierdzam aktualizację wolnych terminów.').'</label><p><button class="button"'.(!$known&&($s['stage']??'')==='planning'&&count($s['planning_attempt_archive']??[])>=3?' disabled':'').'>'.esc_html($known?'Odczytaj zapisany dobór tematów':'Ponów bieżący etap doboru').'</button></p></form>';
                if($known&&in_array($s['response_status']??'',['failed','cancelled','incomplete','completed'],true)&&count($s['planning_attempt_archive']??[])<3){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="zp_prep_auto_retry"><input type="hidden" name="auto_id" value="'.esc_attr($s['id']).'"><input type="hidden" name="retry_fresh_planning" value="1">';wp_nonce_field('zp_prep_auto_retry');echo '<label><input type="checkbox" name="retry_ack" value="1" required> Poprzednia odpowiedź zakończyła się. Świadomie zlecam osobny płatny dobór tematów; poprzedni wynik zachowamy w historii.</label><p><button class="button">Nowy dobór tematów (płatny)</button></p></form>';}
            }
        }echo '</section>';
    }
}
foreach(['zp_prep_auto_start','zp_prep_auto_retry','zp_prep_auto_reuse_research'] as $zp_prep_auto_action){add_action('admin_post_'.$zp_prep_auto_action,static function()use($zp_prep_auto_action){ZP_Content_Auto_Preparation_20261010::handle($zp_prep_auto_action);});}unset($zp_prep_auto_action);
add_action(ZP_Content_Auto_Preparation_20261010::WORKER,[ZP_Content_Auto_Preparation_20261010::class,'worker']);
add_action(ZP_Content_Auto_Preparation_20261010::WATCHDOG,[ZP_Content_Auto_Preparation_20261010::class,'watchdog']);
